"""narrow_copy: Triton implementation of torch.narrow_copy(inp, dim, start, length).

Semantics (verified against torch 2.5.1 reference):
  * negative `dim` is normalized by adding ndim;
  * negative `start` is normalized by adding size(dim);
  * output shape == input shape with output dim `dim` == length; output is
    contiguous; input may have arbitrary strides/layout.

Performance strategy
  * Timed workloads are 2-D with dim==0 and contiguous inputs: a single
    contiguous byte narrow_copy is copied.  The XPU Triton backend's copy throughput
    is bounded per *element*, so the copy is done through an int64 view of the
    payload (8-byte lanes), which for fp16/bf16/fp32 runs 4x/2x fewer elements
    than a native-dtype copy and closes most of the gap to the native
    torch.narrow_copy bandwidth.
  * Multi-row or non-contiguous layouts use an "affine" row-window kernel when
    the layout is dense (tail dims from `dim` form a contiguous suffix and the
    head dims are an affine multiple), otherwise a fully general per-dim
    digit-decomposition kernel (device int64 size/stride arrays).
"""
import math

import torch
import triton
import triton.language as tl

# ---------------------------------------------------------------------------
# fast paths: contiguous single-segment copies
# ---------------------------------------------------------------------------


@triton.jit
def _nc_copy_i64(in_ptr, out_ptr, total, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    m = offs < total
    v = tl.load(in_ptr + offs, mask=m)
    tl.store(out_ptr + offs, v, mask=m)


@triton.jit
def _nc_copy_native(in_ptr, out_ptr, total, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    m = offs < total
    v = tl.load(in_ptr + offs, mask=m)
    tl.store(out_ptr + offs, v, mask=m)


_BLOCK_WIDE = 32768
_WARPS_WIDE = 32
_BLOCK_NATIVE = 4096
_WARPS_NATIVE = 8


def _contig_run(inp, d, s, L):
    """Copy a single contiguous byte narrow_copy: inp narrow (d, s, L) -> fresh out."""
    srcv = inp.narrow(d, s, L)  # zero-copy view, contiguous
    out = torch.empty_like(srcv)
    n = out.numel()
    if n == 0:
        return out
    es = out.element_size()
    obytes = srcv.storage_offset() * es
    nbytes = n * es
    if obytes % 8 == 0 and nbytes % 8 == 0:
        n8 = nbytes // 8
        try:
            srcw = srcv.view(torch.int64)
            outw = out.view(torch.int64)
        except RuntimeError:  # trailing dim not divisible; flatten first
            srcw = srcv.reshape(-1).view(torch.int64)
            outw = out.reshape(-1).view(torch.int64)
        # launch geometry tiers: tiny copies need only a small CTA, the
        # largest copies benefit from the widest tiles.
        if n8 <= 1024:
            BLOCK, WARPS = 1024, 2
        elif n8 <= 8192:
            BLOCK, WARPS = 8192, 8
        elif n8 <= (1 << 18):
            BLOCK, WARPS = 16384, 16
        else:
            BLOCK, WARPS = _BLOCK_WIDE, _WARPS_WIDE
        grid = (triton.cdiv(n8, BLOCK),)
        _nc_copy_i64[grid](srcw, outw, n8, BLOCK=BLOCK, num_warps=WARPS)
    else:
        grid = (triton.cdiv(n, _BLOCK_NATIVE),)
        _nc_copy_native[grid](
            srcv, out, n, BLOCK=_BLOCK_NATIVE, num_warps=_WARPS_NATIVE
        )
    return out


# ---------------------------------------------------------------------------
# dense-layout multi-row path: affine row windows, no per-element division
# ---------------------------------------------------------------------------


@triton.jit
def _nc_affine_kernel(
    in_ptr,
    out_ptr,
    R,
    K,
    SI,
    Cpb,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0).to(tl.int64)
    row = pid // Cpb
    chunk = pid - row * Cpb
    offs = chunk * BLOCK + tl.arange(0, BLOCK).to(tl.int64)
    mask = offs < R
    src = row * K + SI + offs
    dst = row * R + offs
    val = tl.load(in_ptr + src, mask=mask)
    tl.store(out_ptr + dst, val, mask=mask)


# ---------------------------------------------------------------------------
# arbitrary-layout fallback: per-dim digit decomposition
# ---------------------------------------------------------------------------


@triton.jit
def _nc_general_kernel(
    in_ptr,
    out_ptr,
    sz_ptr,
    st_ptr,
    total,
    L,
    S,
    ND: tl.constexpr,
    D: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0).to(tl.int64)
    offs = pid * BLOCK + tl.arange(0, BLOCK).to(tl.int64)
    mask = offs < total
    f = offs
    acc = tl.zeros((BLOCK,), dtype=tl.int64)
    for j in tl.static_range(ND - 1, -1, -1):
        if j == D:
            idx = f % L
            f = f // L
            idx = idx + S
        else:
            sz = tl.load(sz_ptr + j)
            idx = f % sz
            f = f // sz
        st = tl.load(st_ptr + j)
        acc += idx * st
    val = tl.load(in_ptr + acc, mask=mask)
    tl.store(out_ptr + offs, val, mask=mask)


_BLOCK_AFFINE = 1024
_WARPS_AFFINE = 4
_BLOCK_GEN = 256
_WARPS_GEN = 4


def _scalar(v):
    if isinstance(v, torch.Tensor):
        return int(v.item())
    return int(v)


def narrow_copy(inp, dim, start, length):
    with torch_device_fn.device(inp.device):
        nd = inp.dim()
        d = _scalar(dim)
        if d < 0:
            d += nd
        s = _scalar(start)
        L = _scalar(length)
        if s < 0:
            s += inp.shape[d]

        shape = inp.shape

        # ---- single contiguous narrow_copy (contiguous input, head dims all size 1) ----
        single = inp.is_contiguous()
        if single:
            for j in range(d):
                if shape[j] != 1:
                    single = False
                    break
        if single:
            return _contig_run(inp, d, s, L)

        # ---- general path ------------------------------------------------
        out_shape = list(shape)
        out_shape[d] = L
        out = torch.empty(out_shape, dtype=inp.dtype, device=inp.device)
        total = out.numel()
        if total == 0:
            return out

        sz = shape
        st = inp.stride()

        input_view = 1
        for j in range(d + 1, nd):
            input_view *= sz[j]

        tail_ok = True
        p = 1
        for j in range(nd - 1, d - 1, -1):
            if st[j] != p:
                tail_ok = False
                break
            p *= sz[j]

        head_ok = True
        K = 0
        if tail_ok and d > 0:
            K = st[d - 1]
            q = sz[d - 1]
            for j in range(d - 2, -1, -1):
                if st[j] != K * q:
                    head_ok = False
                    break
                q *= sz[j]

        if tail_ok and head_ok:
            R = L * input_view
            output_ptr = math.prod(sz[:d])
            cpb = (R + _BLOCK_AFFINE - 1) // _BLOCK_AFFINE
            grid = (output_ptr * cpb,)
            _nc_affine_kernel[grid](
                inp,
                out,
                R,
                K,
                s * input_view,
                cpb,
                BLOCK=_BLOCK_AFFINE,
                num_warps=_WARPS_AFFINE,
            )
        else:
            dev_sz = torch.tensor(tuple(sz), dtype=torch.int64, device=inp.device)
            dev_st = torch.tensor(tuple(st), dtype=torch.int64, device=inp.device)
            grid = (triton.cdiv(total, _BLOCK_GEN),)
            _nc_general_kernel[grid](
                inp,
                out,
                dev_sz,
                dev_st,
                total,
                L,
                s,
                ND=nd,
                D=d,
                BLOCK=_BLOCK_GEN,
                num_warps=_WARPS_GEN,
            )
        return out
